    @Wire("computer_id") val computerId: ComputerId,
    @Wire("wake") val wake: WakeSetting
)

/**
 * Decoded body of a wake ticket. Ed25519-signed by cloud-api. Single use per jti.
 */
data class WakeTicketClaims(
    @Wire("v") val v: Long,
    @Wire("typ") val typ: String,
    @Wire("sub") val sub: String,
    @Wire("computer_id") val computerId: ComputerId,
    @Wire("reason") val reason: WakeReason,
    @Wire("device_id") val deviceId: DeviceId,
    @Wire("iat") val iat: Long,
    @Wire("exp") val exp: Long,
    @Wire("jti") val jti: String,
    @Wire("kid") val kid: String
)

data class WhoAmIResponse(
    @Wire("principal") val principal: PrincipalRef,
    @Wire("computer_id") val computerId: ComputerId,
    @Wire("grants") val grants: List<RootGrant>,
    @Wire("freshness") val freshness: Freshness
)
